def configure(get_user_econ=None, get_chat_settings=None):
    """Attach bot-specific data accessors without importing the monolith."""
    global _get_user_econ, _get_chat_settings
    if get_user_econ is not None:
        _get_user_econ = get_user_econ
    if get_chat_settings is not None:
        _get_chat_settings = get_chat_settings


def set_locale_context(user_id=None, chat_id=None):
    _LOCALE_CONTEXT.user_id = user_id
    _LOCALE_CONTEXT.chat_id = chat_id


def clear_locale_context():
    _LOCALE_CONTEXT.user_id = None
    _LOCALE_CONTEXT.chat_id = None


def set_callback_language(callback_id, lang):
    lang = str(lang or DEFAULT_LANGUAGE).lower()
    if lang not in SUPPORTED_LANGUAGES:
        lang = DEFAULT_LANGUAGE
    with _CALLBACK_LANG_LOCK:
        _CALLBACK_LANG_BY_ID[str(callback_id)] = (lang, time.time())


def clear_callback_language(callback_id):
    with _CALLBACK_LANG_LOCK:
        _CALLBACK_LANG_BY_ID.pop(str(callback_id), None)


def _current_locale_user_id(default=None):
    return getattr(_LOCALE_CONTEXT, "user_id", None) or default


def _bot_output_language(chat_id, user_id=None):
    try:
        cid = int(chat_id)
    except Exception:
        return DEFAULT_LANGUAGE

    try:
        if cid > 0:
            if _get_user_econ is None:
                return DEFAULT_LANGUAGE
            econ = _get_user_econ(user_id=user_id or cid)
            lang = econ.get("language", DEFAULT_LANGUAGE) if econ else DEFAULT_LANGUAGE
        else:
            if _get_chat_settings is None:
                return DEFAULT_LANGUAGE
            lang = _get_chat_settings(cid).get("language", DEFAULT_LANGUAGE)

        lang = str(lang or DEFAULT_LANGUAGE).lower()
        return lang if lang in SUPPORTED_LANGUAGES else DEFAULT_LANGUAGE
    except Exception:
        return DEFAULT_LANGUAGE


def _localize_bot_text(text, lang):
    if not isinstance(text, str) or lang == DEFAULT_LANGUAGE:
        return text

    out = text

    # Protect complete code blocks and user-controlled tokens from replacement.
    protected = []

    def protect(match):
        protected.append(match.group(0))
        return f"\\x00PROT{len(protected)-1}\\x00"

    out = re.sub(
        r"<code>.*?</code>|<pre>.*?</pre>|https?://\\S+|tg://\\S+|@[A-Za-z0-9_]{3,}|(?<![A-Za-z0-9_])/[A-Za-z0-9_]+",
        protect,
        out,
        flags=re.DOTALL,
    )
    out = re.sub(r"<[^>]+>", protect, out)

    for src, dst in sorted(
        _LOCALE_PHRASES.get(lang, {}).items(),
        key=lambda kv: len(kv[0]),
        reverse=True,
    ):
        out = out.replace(src, dst)

    words = _LOCALE_WORDS.get(lang, {})
    if words:
        def repl(match):
            word = match.group(0)
            translated = words.get(word.lower())
            if not translated:
                return word
            if word[:1].isupper():
                translated = translated[:1].upper() + translated[1:]
            return translated

        out = re.sub(r"[А-Яа-яЁё]+", repl, out)

    for i, value in enumerate(protected):
        out = out.replace(f"\\x00PROT{i}\\x00", value)

    return out


def localize_text(text, lang=DEFAULT_LANGUAGE):
    """Public alias for text localization."""
    return _localize_bot_text(text, lang)


def _localize_markup(markup, lang):
    if markup is None or lang == DEFAULT_LANGUAGE:
        return markup

    try:
        markup_copy = copy.deepcopy(markup)

        for rows_name in ("inline_keyboard", "keyboard"):
            rows = getattr(markup_copy, rows_name, None)
            if rows:
                for row in rows:
                    for button in row:
                        if hasattr(button, "text") and isinstance(button.text, str):
                            button.text = _localize_bot_text(button.text, lang)

        return markup_copy
    except Exception:
        return markup


def format_large_numbers(text):
    """Format large plain integers while preserving HTML tags and IDs."""
    if not isinstance(text, str) or not text:
        return text

    parts = re.split(r"(<[^>]+>)", text)
    number_re = re.compile(r"(?<![\\d,.])\\d{4,}(?![\\d,.])")

    def repl(match):
        raw = match.group(0)
        if len(raw) == 4 and raw.isdigit() and 1900 <= int(raw) <= 2099:
            return raw
        try:
            return f"{int(raw):,}"
        except (TypeError, ValueError):
            return raw

    for i, part in enumerate(parts):
        if not (part.startswith("<") and part.endswith(">")):
            parts[i] = number_re.sub(repl, part)

    return "".join(parts)


def apply_global_premium_emojis(text):
    """Replace normal UI emoji with Telegram Custom Emoji in HTML text."""
    if not isinstance(text, str) or not text:
        return text

    text = format_large_numbers(text)

    protected = []

    def protect(match):
        protected.append(match.group(0))
        return f"\\x00TGEMOJI{len(protected)-1}\\x00"

    text = re.sub(
        r"<tg-emoji\\b[^>]*>.*?</tg-emoji>",
        protect,
        text,
        flags=re.DOTALL,
    )

    for emoji in sorted(GLOBAL_PREMIUM_EMOJI_MAP, key=len, reverse=True):
        alias = GLOBAL_PREMIUM_EMOJI_MAP[emoji]
        text = text.replace(emoji, premium_emoji(alias, emoji))

    for i, tag in enumerate(protected):
        text = text.replace(f"\\x00TGEMOJI{i}\\x00", tag)

    return text


def _localized_media_object(media, lang):
    if media is None:
        return media

    media_copy = copy.deepcopy(media)
    if hasattr(media_copy, "caption") and media_copy.caption:
        media_copy.caption = _localize_bot_text(media_copy.caption, lang)

    return media_copy


def _callback_language(callback_query_id):
    with _CALLBACK_LANG_LOCK:
        now = time.time()
        stale = [
            key
            for key, value in _CALLBACK_LANG_BY_ID.items()
            if now - float(value[1]) > 300
        ]
        for key in stale:
            _CALLBACK_LANG_BY_ID.pop(key, None)

        item = _CALLBACK_LANG_BY_ID.get(str(callback_query_id))
        return item[0] if item else DEFAULT_LANGUAGE


def install_telegram_localization(bot):
    """Install the final localization + Premium Emoji wrappers on a TeleBot.

    Safe to call once per bot instance. Calling it again on the same instance
    is ignored to prevent wrapper stacking.
    """
    if getattr(bot, "_nya_localization_installed", False):
        return bot

    original_send_message = bot.send_message
    original_reply_to = bot.reply_to
    original_edit_text = bot.edit_message_text
    original_answer_callback = bot.answer_callback_query

    original_edit_caption = getattr(bot, "edit_message_caption", None)
    original_edit_media = getattr(bot, "edit_message_media", None)
    original_send_photo = getattr(bot, "send_photo", None)
    original_send_animation = getattr(bot, "send_animation", None)
    original_send_video = getattr(bot, "send_video", None)
    original_send_invoice = getattr(bot, "send_invoice", None)

    def transform(text):
        return apply_global_premium_emojis(text)

    def send_message(chat_id, text, *args, **kwargs):
        uid_override = kwargs.pop("user_id", None)
        lang = _bot_output_language(
            chat_id,
            _current_locale_user_id(uid_override),
        )
        if "reply_markup" in kwargs:
            kwargs["reply_markup"] = _localize_markup(kwargs["reply_markup"], lang)

        if kwargs.get("parse_mode") == "HTML":
            original_text = text
            transformed = transform(_localize_bot_text(text, lang))
            try:
                return original_send_message(chat_id, transformed, *args, **kwargs)
            except Exception as exc:
                if _is_premium_markup_error(exc):
                    return original_send_message(chat_id, _localize_bot_text(original_text, lang), *args, **kwargs)
                raise

        return original_send_message(chat_id, _localize_bot_text(text, lang), *args, **kwargs)

    def reply_to(message, text, *args, **kwargs):
        lang = _bot_output_language(
            message.chat.id,
            getattr(message.from_user, "id", None),
        )
        if "reply_markup" in kwargs:
            kwargs["reply_markup"] = _localize_markup(kwargs["reply_markup"], lang)

        if kwargs.get("parse_mode") == "HTML":
            original_text = text
            transformed = transform(_localize_bot_text(text, lang))
            try:
                return original_reply_to(message, transformed, *args, **kwargs)
            except Exception as exc:
                if _is_premium_markup_error(exc):
                    return original_reply_to(message, _localize_bot_text(original_text, lang), *args, **kwargs)
                raise

        return original_reply_to(message, _localize_bot_text(text, lang), *args, **kwargs)

    def edit_message_text(text, chat_id, message_id, *args, **kwargs):
        lang = _bot_output_language(chat_id, _current_locale_user_id())
        if "reply_markup" in kwargs:
            kwargs["reply_markup"] = _localize_markup(kwargs["reply_markup"], lang)

        if kwargs.get("parse_mode") == "HTML":
            original_text = text
            transformed = transform(_localize_bot_text(text, lang))
            try:
                return original_edit_text(transformed, chat_id, message_id, *args, **kwargs)
            except Exception as exc:
                if _is_premium_markup_error(exc):
                    return original_edit_text(_localize_bot_text(original_text, lang), chat_id, message_id, *args, **kwargs)
                raise

        return original_edit_text(_localize_bot_text(text, lang), chat_id, message_id, *args, **kwargs)

    def answer_callback_query(callback_query_id, text=None, *args, **kwargs):
        lang = _callback_language(callback_query_id)
        if text is not None:
            text = _localize_bot_text(text, lang)
        return original_answer_callback(callback_query_id, text, *args, **kwargs)

    def edit_message_caption(caption, chat_id=None, message_id=None, *args, **kwargs):
        if original_edit_caption is None:
            raise AttributeError("edit_message_caption is unavailable")

        lang = _bot_output_language(chat_id, _current_locale_user_id())
        if "reply_markup" in kwargs:
            kwargs["reply_markup"] = _localize_markup(kwargs["reply_markup"], lang)

        if kwargs.get("parse_mode") == "HTML":
            original_caption = caption
            transformed = transform(_localize_bot_text(caption, lang))
            try:
                return original_edit_caption(transformed, chat_id, message_id, *args, **kwargs)
            except Exception as exc:
                if _is_premium_markup_error(exc):
                    return original_edit_caption(_localize_bot_text(original_caption, lang), chat_id, message_id, *args, **kwargs)
                raise

        return original_edit_caption(_localize_bot_text(caption, lang), chat_id, message_id, *args, **kwargs)

    def localized_media_sender(original, chat_id, media, *args, **kwargs):
        lang = _bot_output_language(chat_id, _current_locale_user_id())

        if "reply_markup" in kwargs:
            kwargs["reply_markup"] = _localize_markup(kwargs["reply_markup"], lang)

        if kwargs.get("caption") is not None:
            caption = _localize_bot_text(kwargs["caption"], lang)
            if kwargs.get("parse_mode") == "HTML":
                caption = transform(caption)
            kwargs["caption"] = caption

        try:
            return original(chat_id, media, *args, **kwargs)
        except Exception as exc:
            if _is_premium_markup_error(exc) and kwargs.get("caption"):
                kwargs["caption"] = _localize_bot_text(kwargs["caption"], lang)
                kwargs["caption"] = re.sub(
                    r"<tg-emoji\\b[^>]*>.*?</tg-emoji>",
                    "",
                    kwargs["caption"],
                    flags=re.DOTALL,
                )
                return original(chat_id, media, *args, **kwargs)
            raise

    def send_photo(chat_id, photo, *args, **kwargs):
        return localized_media_sender(original_send_photo, chat_id, photo, *args, **kwargs)

    def send_animation(chat_id, animation, *args, **kwargs):
        return localized_media_sender(original_send_animation, chat_id, animation, *args, **kwargs)

    def send_video(chat_id, video, *args, **kwargs):
        return localized_media_sender(original_send_video, chat_id, video, *args, **kwargs)

    def edit_message_media(media, chat_id=None, message_id=None, *args, **kwargs):
        if original_edit_media is None:
            raise AttributeError("edit_message_media is unavailable")

        lang = _bot_output_language(chat_id, _current_locale_user_id())
        if "reply_markup" in kwargs:
            kwargs["reply_markup"] = _localize_markup(kwargs["reply_markup"], lang)

        localized_media = _localized_media_object(media, lang)
        if getattr(localized_media, "caption", None):
            parse_mode = getattr(localized_media, "parse_mode", None)
            if parse_mode == "HTML":
                localized_media.caption = transform(localized_media.caption)

        try:
            return original_edit_media(
                localized_media,
                chat_id=chat_id,
                message_id=message_id,
                *args,
                **kwargs,
            )
        except Exception as exc:
            if _is_premium_markup_error(exc) and getattr(localized_media, "caption", None):
                plain_media = copy.deepcopy(localized_media)
                plain_media.caption = re.sub(
                    r"<tg-emoji\\b[^>]*>.*?</tg-emoji>",
                    "",
                    plain_media.caption,
                    flags=re.DOTALL,
                )
                return original_edit_media(
                    plain_media,
                    chat_id=chat_id,
                    message_id=message_id,
                    *args,
                    **kwargs,
                )
            raise

    def send_invoice(
        chat_id,
        title,
        description,
        invoice_payload,
        provider_token,
        currency,
        prices,
        *args,
        **kwargs,
    ):
        if original_send_invoice is None:
            raise AttributeError("send_invoice is unavailable")

        lang = _bot_output_language(chat_id, _current_locale_user_id())
        title = _localize_bot_text(title, lang)
        description = _localize_bot_text(description, lang)

        localized_prices = []
        for price in prices or []:
            try:
                item = copy.deepcopy(price)
                if hasattr(item, "label"):
                    item.label = _localize_bot_text(item.label, lang)
                localized_prices.append(item)
            except Exception:
                localized_prices.append(price)

        return original_send_invoice(
            chat_id,
            title,
            description,
            invoice_payload,
            provider_token,
            currency,
            localized_prices,
            *args,
            **kwargs,
        )

    bot.send_message = send_message
    bot.reply_to = reply_to
    bot.edit_message_text = edit_message_text
    bot.answer_callback_query = answer_callback_query

    if original_edit_caption:
        bot.edit_message_caption = edit_message_caption
    if original_edit_media:
        bot.edit_message_media = edit_message_media
    if original_send_photo:
        bot.send_photo = send_photo
    if original_send_animation:
        bot.send_animation = send_animation
    if original_send_video:
        bot.send_video = send_video
    if original_send_invoice:
        bot.send_invoice = send_invoice

    bot._nya_localization_installed = True
    return bot
